"""Queue implementation using two stacks."""


class QueueFromStacks:
    def __init__(self):
        self._in_stack = []
        self._out_stack = []

    def enqueue(self, item):
        self._in_stack.append(item)

    def dequeue(self):
        if self.is_empty():
            raise IndexError("dequeue from empty queue")
        self._transfer()
        return self._out_stack.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty queue")
        self._transfer()
        return self._out_stack[-1]

    def is_empty(self):
        return not self._in_stack and not self._out_stack

    def __len__(self):
        return len(self._in_stack) + len(self._out_stack)

    def _transfer(self):
        if not self._out_stack:
            while self._in_stack:
                self._out_stack.append(self._in_stack.pop())


if __name__ == "__main__":
    import unittest

    class TestQueueFromStacks(unittest.TestCase):
        def test_enqueue_dequeue_order(self):
            q = QueueFromStacks()
            q.enqueue(1)
            q.enqueue(2)
            q.enqueue(3)
            self.assertEqual(q.dequeue(), 1)
            self.assertEqual(q.dequeue(), 2)
            self.assertEqual(q.dequeue(), 3)

        def test_interleaved_operations(self):
            q = QueueFromStacks()
            q.enqueue(1)
            q.enqueue(2)
            self.assertEqual(q.dequeue(), 1)
            q.enqueue(3)
            self.assertEqual(q.dequeue(), 2)
            self.assertEqual(q.dequeue(), 3)

        def test_peek(self):
            q = QueueFromStacks()
            q.enqueue(10)
            q.enqueue(20)
            self.assertEqual(q.peek(), 10)
            self.assertEqual(q.peek(), 10)  # peek doesn't remove
            self.assertEqual(len(q), 2)

        def test_is_empty(self):
            q = QueueFromStacks()
            self.assertTrue(q.is_empty())
            q.enqueue(1)
            self.assertFalse(q.is_empty())
            q.dequeue()
            self.assertTrue(q.is_empty())

        def test_len(self):
            q = QueueFromStacks()
            self.assertEqual(len(q), 0)
            q.enqueue(1)
            q.enqueue(2)
            self.assertEqual(len(q), 2)
            q.dequeue()
            self.assertEqual(len(q), 1)

        def test_dequeue_empty_raises(self):
            q = QueueFromStacks()
            with self.assertRaises(IndexError):
                q.dequeue()

        def test_peek_empty_raises(self):
            q = QueueFromStacks()
            with self.assertRaises(IndexError):
                q.peek()

        def test_single_element(self):
            q = QueueFromStacks()
            q.enqueue(42)
            self.assertEqual(q.peek(), 42)
            self.assertEqual(q.dequeue(), 42)
            self.assertTrue(q.is_empty())

        def test_large_queue(self):
            q = QueueFromStacks()
            n = 1000
            for i in range(n):
                q.enqueue(i)
            for i in range(n):
                self.assertEqual(q.dequeue(), i)

    unittest.main()
